{
    "name": "opencode-tiny-goal",
    "version": "0.1.4",
    "description": "A tiny goal plugin for opencode 2.x: /goal keeps the agent working until the goal is done, without nagging while background work runs.",
    "keywords": [
        "opencode",
        "opencode-plugin",
        "goal",
        "agent"
    ],
    "license": "WTFPL",
    "author": "Ciyoxe",
    "homepage": "https://github.com/Ciyoxe/opencode-tiny-goal#readme",
    "repository": {
        "type": "git",
        "url": "git+https://github.com/Ciyoxe/opencode-tiny-goal.git"
    },
    "bugs": {
        "url": "https://github.com/Ciyoxe/opencode-tiny-goal/issues"
    },
    "type": "module",
    "main": "src/index.ts",
    "files": [
        "src"
    ],
    "scripts": {
        "typecheck": "tsc --noEmit",
        "test": "vitest run"
    },
    "devDependencies": {
        "@types/node": "^26.6.5",
        "typescript": "^7.0.2",
        "vitest": "^5.0.5"
    }
}
